<script setup>
import { computed, watch, nextTick, onMounted, onBeforeUnmount, reactive, ref } from 'vue'
import { api } from '../api'
import { CreditCard, RefreshCw, Plus, Settings2, ArrowUpRight, CheckCircle2, Clock3, Wallet, CircleDashed, X, ChevronDown, SlidersHorizontal, Search, ShieldCheck, Users, LayoutGrid, List } from 'lucide-vue-next'
import { formatTime } from '../utils'
import { returnStates, returnLabel, tradeKinds, returnTypes, operationStates, caseSummary, summarizeCardBalances, cardHasCase, cardMatchesSearch, readCardView, saveCardView } from '../ejh'
import ReturnStatusBadge from './ReturnStatusBadge.vue'
import ReturnCaseLine from './ReturnCaseLine.vue'
import CardAccountPreview from './CardAccountPreview.vue'
import MessageBar from './MessageBar.vue'
import Pagination from './Pagination.vue'
const props=defineProps({entry:{type:Object,default:null}})
const emit=defineEmits(['entry-applied'])
const cardView=ref(readCardView(window.localStorage))
const targetCardID=ref('')
function setCardView(value){cardView.value=value;saveCardView(window.localStorage,value)}
const tab=ref('cards'),busy=ref(false),ready=ref(false),message=reactive({text:'',type:''})
const settings=reactive({enabled:false,url:'https://www.ejhcard.com',app_key:'',app_secret:'',default_max_accounts:3,sync_enabled:false,sync_interval_seconds:300,alert_hours:24,templates:[]})
const data=ref({cards:[],cases:[],trades:[],operations:[],audit:[],balance:null,sync:{}})
const query=ref(''),status=ref(''),page=ref(1),pageSize=ref(10),detail=ref(null),matching=ref(null),resolving=ref(null)
watch(()=>props.entry,entry=>{
 if(!entry?.email||!entry?.cardID)return
 tab.value='cards';query.value=entry.email;targetCardID.value=entry.cardID;status.value='';page.value=1
 emit('entry-applied')
},{immediate:true})
function clearFilters(){query.value='';status.value='';targetCardID.value='';page.value=1}
const dates=reactive({start:'',end:''}),openForm=reactive({template:'',count:1,request_id:'',input:null})
const matchForm=reactive({payment_order_id:'',original_trade_id:'',amount:'',currency:'',evidence:'',confirmed:false})
const resolveForm=reactive({order_no:'',outcome:'completed',evidence:''})
const balanceProgress = ref(null), balanceFailures = ref([])
const balanceSummary = computed(() => summarizeCardBalances(data.value.cards))
const syncExpanded = ref(false), settingsTab = ref('connection'), managedID = ref('')
const managedCard = computed(() => data.value.cards.find(c => c.id === managedID.value))
const tableTabs = [['cards','卡片管理'],['cases','账号回款'],['trades','撤销 / 退款对账'],['operations','操作记录'],['audit','核对审计']]
const statIcons = { unopened: CircleDashed, opened: CreditCard, waiting: Clock3, returned: CheckCircle2 }
const sectionDescriptions = { cards:'查看卡片状态、已开通账号和剩余名额。', cases:'每个账号的一次性回款状态与核对记录。', trades:'核对原交易与回款归属，不按金额或时间猜测。', operations:'开卡、追加额度和销卡的执行结果。', audit:'保留关联、更正及核实依据，便于追溯。' }
function cardStatus(card) {
 if (card.error) return '资料待核实'
 if (card.remote.isLocked === '1') return '已冻结'
 return { '1':'已激活', '2':'已销卡', '3':'可用' }[card.remote.status] || '状态待核实'
}
function capacityPercent(card) { return Math.min(100, ((card.local?.opened_accounts || 0) + (card.local?.pending_accounts || 0)) / (card.local?.account_limit || settings.default_max_accounts) * 100) }
function expiryLabel(value) { return /^\d{4}$/.test(value || '') ? value.slice(0,2) + ' / ' + value.slice(2) : value || '未提供' }
function closeOverlay() { if (busy.value) return; detail.value=null;matching.value=null;resolving.value=null;managedID.value='' }
function revealInvalid(event) {
 event.preventDefault()
 const group=event.target.closest('[data-settings-tab]')
 if(group) settingsTab.value=group.dataset.settingsTab
 for(let parent=event.target.parentElement;parent;parent=parent.parentElement) if(parent.tagName==='DETAILS') parent.open=true
 show(event.target.validationMessage || '请检查输入内容','error')
 nextTick(()=>event.target.focus())
}
function keydown(event) { if(event.key==='Escape') closeOverlay() }
let disposed=false
const tabs=[['cards','卡片管理'],['cases','账号回款'],['trades','撤销 / 退款对账'],['operations','操作记录'],['audit','核对审计'],['open','开卡'],['settings','配置与模板']]
const filtered=computed(()=>(data.value[tab.value]||[]).filter(row=>{
 if(tab.value==='cards'){if(!cardMatchesSearch(row,data.value.cases,query.value,targetCardID.value))return false}
 else if(query.value&&!JSON.stringify(row).toLowerCase().includes(query.value.trim().toLowerCase()))return false
 if(!status.value)return true
 if(tab.value==='cases')return row.state===status.value
 if(tab.value==='trades')return status.value==='unmatched'?returnTypes.has(row.trade.tradeType)&&!row.payment_order_id:status.value==='returned'?row.confirmed:status.value==='pending'?returnTypes.has(row.trade.tradeType)&&!row.confirmed:!returnTypes.has(row.trade.tradeType)
 return true
}))
const visible=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value))
const counts=computed(()=>Object.fromEntries(Object.keys(returnStates).map(k=>[k,data.value.cases.filter(c=>c.state===k).length])))
const matchingOrders=computed(()=>data.value.cases.filter(c=>cardHasCase({id:matching.value?.card_id},c)&&c.payment_status==='success'))
const originals=computed(()=>data.value.trades.filter(t=>t.card_id===matching.value?.card_id&&['1','4'].includes(t.trade.tradeType)))
function changeTab(v){tab.value=v;clearFilters();detail.value=null}
function show(text,type='success'){message.text=text;message.type=type}
async function action(fn){if(busy.value)return;busy.value=true;message.text='';try{await fn()}catch(e){show(e.message,'error')}finally{busy.value=false}}
async function load(){const result=await api('/api/ejh/dashboard');if(!disposed)data.value=result}
async function save(){await action(async()=>{const result=await api('/api/ejh/settings',{method:'PUT',body:settings});Object.assign(settings,result,{app_secret:''});show('EJH 配置已保存')})}
async function test(){await action(async()=>{await api('/api/ejh/test',{method:'POST',body:{}});await load();show('连接成功，余额已更新（使用已保存配置）')})}
async function refreshAllBalances() {
 await action(async () => {
  balanceFailures.value=[]
  await load()
  if(disposed) return
  const cards=[...data.value.cards]
  balanceProgress.value={done:0,total:cards.length+1}
  try {
   try { await api('/api/ejh/balance',{method:'POST',body:{}}) }
   catch(e) { balanceFailures.value.push({label:'账户余额',error:e.message}) }
   balanceProgress.value.done++
   await load()
   for(const card of cards) {
    if(disposed) return
    try { await api('/api/ejh/cards/'+encodeURIComponent(card.id)+'/action',{method:'POST',body:{action:'balance'}}) }
    catch(e) { balanceFailures.value.push({label:card.local?.name || card.remote.orderNo,error:e.message}) }
    balanceProgress.value.done++
   }
   if(!disposed) await load()
   show(balanceFailures.value.length ? '余额刷新完成，'+balanceFailures.value.length+' 项失败，保留原余额。' : '账户及全部 '+cards.length+' 张卡片余额已刷新并保存。',balanceFailures.value.length?'error':'success')
  } finally { balanceProgress.value=null }
 })
}
async function queryAccountBalance() { await action(async()=>{await api('/api/ejh/balance',{method:'POST',body:{}});await load();show('账户余额已查询并保存')}) }
async function sync(){await action(async()=>{try{await api('/api/ejh/sync',{method:'POST',body:dates});show('卡片和流水已同步')}finally{await load()}})}
function addTemplate(){settings.templates.push({id:crypto.randomUUID(),name:'新模板',valid_days:30,cardType:'',cardAmount:'',cardCurrency:'USD',billCurrency:'USD',useTime:1,companyRate:'0.01',activeDate:'',supportedMccGroup:'ecom',extInfoyx:'',OrderTitle:'',OrderGuestName:'',OrderActiveDate:'',OrderExpiryDate:'',amount:''})}
function chooseTemplate(){const t=settings.templates.find(t=>t.id===openForm.template);if(!t){openForm.input=null;return}const d=new Date(Date.now()+t.valid_days*86400000);openForm.input={...t,activeDate:d.toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'})};delete openForm.input.id;delete openForm.input.name;delete openForm.input.valid_days;openForm.request_id=''}
async function openCards(){if(!openForm.input||!Number.isInteger(openForm.count)||openForm.count<1||openForm.count>50)return show('请选择模板，数量须为 1～50','error');if(!window.confirm('确认真实开卡 '+openForm.count+' 张？每张额度 '+openForm.input.cardAmount+' '+openForm.input.cardCurrency+'，另有卡台费用。结果未知时停止，不自动重试。'))return;await action(async()=>{let done=0;for(let i=0;i<openForm.count;i++){openForm.request_id ||=crypto.randomUUID();const result=await api('/api/ejh/open',{method:'POST',body:{request_id:openForm.request_id,input:openForm.input}});if(result.status!=='completed'){await load();throw new Error('开卡状态：'+operationStates[result.status]+'。'+(result.error||'')+' 请到操作记录核实。')}done++;openForm.request_id='';await load()}show('已开卡 '+done+' 张并加入 Pro 银行卡信息')})}
function cardCases(card){return data.value.cases.filter(c=>cardHasCase(card,c))}
function hoverAccounts(card){return cardCases(card).slice(0,30).map(caseSummary).join('\n')||'暂无关联账号'}
function showAccounts(card){detail.value={title:(card.local?.name||card.remote.orderNo)+' · 关联账号',cases:cardCases(card)}}
async function cardAction(card,act){let amount='';if(act==='increase'){amount=window.prompt('输入追加刷卡额度（不是目标总额）');if(!amount)return}if(['increase','cancel'].includes(act)&&!window.confirm(act==='cancel'?'确认向 EJH 申请销卡？这不是订阅退款操作。':'确认追加 '+amount+' '+card.remote.cardCurrency+'？可能产生费用。'))return;await action(async()=>{const result=await api('/api/ejh/cards/'+encodeURIComponent(card.id)+'/action',{method:'POST',body:{action:act,amount,request_id:crypto.randomUUID(),confirm:true}});await load();if(act==='details')detail.value={title:'卡片敏感信息（关闭即清除）',data:result};else if(['increase','cancel'].includes(act)&&!['completed','resolved'].includes(result.status))throw new Error(operationStates[result.status]+'：'+(result.error||'请核对操作记录'));else show('操作已完成')})}
async function editLimit(card){const v=window.prompt('每卡最大开通数；0 沿用 EJH 默认。回款不返还名额。',card.local?.max_accounts||0);if(v===null)return;const n=Number(v);if(!Number.isInteger(n)||n<0||n>10000)return show('请输入 0～10000 的整数','error');await action(async()=>{await api('/api/gptpay/cards/'+encodeURIComponent(card.id),{method:'PUT',body:{max_accounts:n}});await load();show('单卡上限已保存')})}
async function toggle(card){await action(async()=>{await api('/api/gptpay/cards/'+encodeURIComponent(card.id),{method:'PUT',body:{enabled:!card.local.enabled}});await load()})}
function match(row){matching.value=row;Object.assign(matchForm,{payment_order_id:row.payment_order_id||'',original_trade_id:row.original_trade_id||'',amount:row.confirmed_amount||row.trade.refundBuyPrice||'',currency:row.confirmed_currency||'',evidence:'',confirmed:false})}
async function saveMatch(){await action(async()=>{await api('/api/ejh/trades/'+matching.value.id+'/match',{method:'PUT',body:matchForm});matching.value=null;await load();show('核实结果及依据已保存')})}
async function unmatch(row){const reason=window.prompt('填写解除关联依据（不会修改卡台流水）');if(!reason)return;await action(async()=>{await api('/api/ejh/trades/'+row.id+'/unmatch',{method:'POST',body:{reason}});await load();show('关联已解除，审计保留')})}
function resolve(row){resolving.value=row;Object.assign(resolveForm,{order_no:row.order_no||'',outcome:'completed',evidence:''})}
async function saveResolve(){await action(async()=>{await api('/api/ejh/operations/'+resolving.value.id+'/resolve',{method:'POST',body:resolveForm});resolving.value=null;await load();show('核实结果已保存')})}
function overdue(c){return c.state==='waiting'&&c.requested_at&&Date.now()-Date.parse(c.requested_at)>settings.alert_hours*3600000}
onMounted(()=>window.addEventListener('keydown',keydown))
onMounted(()=>action(async()=>{const cfg=await api('/api/ejh/settings');if(disposed)return;Object.assign(settings,cfg);await load();ready.value=true}))
onBeforeUnmount(()=>{window.removeEventListener('keydown',keydown);disposed=true;settings.app_secret='';detail.value=null})
</script>
<template>
 <div class="view-stack ejh-view">
  <header class="ejh-heading"><div><span class="overline">CARD OPERATIONS</span><h1>EJH 卡台</h1><p>卡片、开通账号与回款记录，一个地方查看。</p></div><div class="ejh-toolbar"><button class="btn ghost" :class="{selected:tab==='settings'}" @click="changeTab('settings')"><Settings2 :size="16"/>配置与模板</button><button class="btn primary" @click="changeTab('open')"><Plus :size="16"/>新建卡片</button></div></header>
  <MessageBar v-if="message.text" :message="message"/>
  <div class="ejh-stats"><button v-for="(label,key) in returnStates" :key="key" :class="['ejh-stat',key,{selected:tab==='cases'&&status===key}]" @click="changeTab('cases');status=key"><span class="ejh-stat-icon"><component :is="statIcons[key]" :size="21"/></span><span class="ejh-stat-value"><ReturnStatusBadge :state="key"/><strong>{{counts[key]||0}}<em>条订单</em></strong></span><ArrowUpRight :size="16"/></button></div>
  <section class="ejh-balance-overview" aria-label="余额总览">
   <header><div><Wallet :size="18"/><h2>余额总览</h2><span>仅点击按钮更新</span></div><button class="btn primary" type="button" :disabled="busy||!ready" @click="refreshAllBalances"><RefreshCw :size="15" :class="{spin:balanceProgress}"/>{{balanceProgress ? '刷新中 '+balanceProgress.done+' / '+balanceProgress.total : '一键刷新全部余额'}}</button></header>
   <div class="ejh-balance-columns">
    <div class="ejh-balance-account"><div class="ejh-balance-label"><span>账户总额 · 按币种</span><button class="ejh-text-button" type="button" :disabled="busy||!ready" @click="queryAccountBalance">查询账户余额</button></div><div v-if="data.balance?.data?.abroadList?.length" class="ejh-balance-values"><div v-for="b in data.balance.data.abroadList" :key="b.currency"><strong>{{b.balance}}</strong><span>{{b.currency}}</span></div></div><div v-else class="ejh-balance-placeholder">{{data.balance?.at?'供应商未返回币种余额':'尚未查询'}}</div><small>上次查询：{{formatTime(data.balance?.at)}}</small></div>
    <div class="ejh-balance-cards"><div class="ejh-balance-label"><span>所有卡片余额汇总</span><span>{{balanceSummary.known}} / {{balanceSummary.total}} 张已查询</span></div><div v-if="balanceSummary.totals.length" class="ejh-balance-values"><div v-for="b in balanceSummary.totals" :key="b.currency"><strong>{{b.amount}}</strong><span>{{b.currency}} <small>· {{b.count}} 张</small></span></div></div><div v-else class="ejh-balance-placeholder">尚无可汇总的余额</div><small>按上次查询结果汇总，含停用 / 已销卡记录，不受分页与筛选影响。<span v-if="balanceSummary.missing"> {{balanceSummary.missing}} 张未查询或数据无效，未计入。</span><span v-if="balanceSummary.failed" class="danger-text"> {{balanceSummary.failed}} 张最近查询失败，有旧值的仍按旧值计入。</span></small></div>
   </div><p class="ejh-balance-note">账户余额与卡内余额分别展示，不相加；不同币种不折算。离开页面会停止尚未开始的批量查询，已完成结果保留。</p>
   <details v-if="balanceFailures.length" class="ejh-balance-errors"><summary>查看 {{balanceFailures.length}} 项查询失败详情</summary><p v-for="(f,i) in balanceFailures" :key="i">{{f.label}}：{{f.error}}</p></details>
  </section>
  <div class="ejh-statusbar"><span class="ejh-connection"><i :class="{enabled:settings.enabled}"></i>{{settings.enabled?'接口已启用':'接口未启用'}}</span><span class="ejh-last-sync">最近同步 {{formatTime(data.sync?.last_success)}}</span><button type="button" class="ejh-text-button" :aria-expanded="syncExpanded" @click="syncExpanded=!syncExpanded"><RefreshCw :size="14"/>流水同步<ChevronDown :size="14" :class="{rotated:syncExpanded}"/></button><button class="ejh-text-button" :disabled="busy" @click="action(load)">刷新本地记录</button></div>
  <section v-if="syncExpanded" class="panel ejh-sync-panel"><div class="ejh-section-heading"><div><h2>同步卡片与流水</h2><p>只读取供应商数据，不触发开卡或付款。</p></div><button class="btn ghost" :disabled="busy||!ready" @click="test">测试连接 / 更新余额</button></div><div class="ejh-sync-fields"><label class="field"><span>同步开始</span><input v-model="dates.start" type="date"/></label><label class="field"><span>结束日期</span><input v-model="dates.end" type="date"/></label><button class="btn" :disabled="busy||!ready" @click="sync">同步卡片与流水</button></div><p v-if="data.sync?.error" class="danger-text">{{data.sync.error}}</p><div class="ejh-toolbar"><span v-for="b in data.balance?.data?.abroadList||[]" :key="b.currency" class="ejh-balance">{{b.currencyName||b.currency}} <strong>{{b.balance}}</strong></span></div></section>
  <nav class="ejh-tabs" aria-label="EJH 管理分区"><button v-for="[id,label] in tableTabs" :key="id" :aria-current="tab===id?'page':undefined" :class="{active:tab===id}" @click="changeTab(id)">{{label}}<span v-if="id==='cards'">{{data.cards.length}}</span></button></nav>
  <form v-if="tab==='settings'" class="panel ejh-settings" @submit.prevent="save" @invalid.capture="revealInvalid">
   <div class="ejh-section-heading"><div><span class="overline">CONFIGURATION</span><h2>配置与模板</h2><p>接口凭证与开卡参数分开管理，修改后统一保存。</p></div></div>
   <nav class="ejh-settings-nav" aria-label="EJH 配置分组"><button type="button" :class="{active:settingsTab==='connection'}" @click="settingsTab='connection'">接口与同步</button><button type="button" :class="{active:settingsTab==='templates'}" @click="settingsTab='templates'">开卡模板 <span>{{settings.templates.length}}</span></button></nav>
   <section v-show="settingsTab==='connection'" data-settings-tab="connection"><div class="ejh-grid"><label class="toggle-row wide"><div><strong>启用 EJH 接口</strong><small>开启后允许查询和卡片操作，自动开卡需单独配置。</small></div><input v-model="settings.enabled" type="checkbox"/><i></i></label><label class="field"><span>HTTPS 地址</span><input v-model="settings.url" required/></label><label class="field"><span>AppKey</span><input v-model="settings.app_key" autocomplete="off"/></label><label class="field"><span>AppSecret</span><input v-model="settings.app_secret" type="password" autocomplete="new-password" :placeholder="settings.secret_present?'已保存，留空不修改':'填写密钥'"/></label><label class="field"><span>EJH 每卡默认最大开通数</span><input v-model.number="settings.default_max_accounts" type="number" min="1" max="10000" required/></label><label class="toggle-row wide"><div><strong>自动同步流水</strong><small>定时读取卡台记录，不发起退款或撤销。</small></div><input v-model="settings.sync_enabled" type="checkbox"/><i></i></label><label class="field"><span>同步间隔（秒）</span><input v-model.number="settings.sync_interval_seconds" type="number" min="60" max="86400" required/></label><label class="field"><span>待回款提醒（小时）</span><input v-model.number="settings.alert_hours" type="number" min="1" max="8760" required/></label></div></section>
   <section v-show="settingsTab==='templates'" data-settings-tab="templates"><div class="ejh-section-heading"><div><h3>已保存模板</h3><p>卡类型由 EJH 分配，点击模板展开编辑。红色 <span class="ejh-required" aria-hidden="true">*</span> 为必填项（含默认选项）。</p></div><button class="btn ghost" type="button" @click="addTemplate"><Plus :size="15"/>增加模板</button></div><details v-for="(t,index) in settings.templates" :key="t.id" class="ejh-template"><summary><CreditCard :size="18"/><span><strong>{{t.name || '新模板'}}</strong><small>{{t.cardAmount || '待设置额度'}} {{t.cardCurrency}} · {{t.valid_days}} 天</small></span><ChevronDown :size="16"/></summary><div class="template-body"><div class="ejh-grid"><label class="field"><span>模板名称 <span class="ejh-required" aria-hidden="true">*</span></span><input v-model="t.name" required/></label><label class="field"><span>卡类型 cardType <span class="ejh-required" aria-hidden="true">*</span></span><input v-model="t.cardType" required/></label><label class="field"><span>刷卡额度 <span class="ejh-required" aria-hidden="true">*</span></span><input v-model="t.cardAmount" inputmode="decimal" required/></label><label class="field"><span>卡币种 <span class="ejh-required" aria-hidden="true">*</span></span><input v-model="t.cardCurrency" maxlength="3" required/></label><label class="field"><span>结算币种 <span class="ejh-required" aria-hidden="true">*</span></span><input v-model="t.billCurrency" maxlength="3" required/></label><label class="field"><span>有效天数 <span class="ejh-required" aria-hidden="true">*</span></span><input v-model.number="t.valid_days" type="number" min="1" max="3650" required/></label><label class="field"><span>使用方式 <span class="ejh-required" aria-hidden="true">*</span></span><select v-model.number="t.useTime" required><option :value="1">多次</option><option :value="0">单次</option></select></label><label class="field"><span>商户类别 <span class="ejh-required" aria-hidden="true">*</span></span><select v-model="t.supportedMccGroup" required><option value="ecom">电商</option><option value="flight">航空</option><option value="hotel">酒店</option><option value="trv">旅行</option></select></label><label class="field"><span>汇率加成（小数）</span><input v-model="t.companyRate"/></label><label class="field"><span>备注</span><input v-model="t.extInfoyx" maxlength="100"/></label></div><details><summary>可选订单参数</summary><div class="ejh-grid"><label class="field"><span>授权次数（留空不限）</span><input :value="t.authCount" type="number" min="1" @input="t.authCount=$event.target.value?Number($event.target.value):null"/></label><label v-for="[key,label] in [['OrderTitle','订单标题'],['OrderGuestName','客人姓名'],['OrderActiveDate','订单生效日期'],['OrderExpiryDate','订单失效日期'],['amount','订单金额']]" :key="key" class="field"><span>{{label}}</span><input v-model="t[key]"/></label></div></details><button class="btn ghost danger-text" type="button" @click="settings.templates.splice(index,1)">移除模板</button></div></details><div v-if="!settings.templates.length" class="ejh-empty"><CreditCard :size="28"/><strong>还没有开卡模板</strong><p>先添加模板，之后可用于手动开卡或 Pro 自动补卡。</p><button class="btn ghost" type="button" @click="addTemplate">添加第一个模板</button></div></section>
   <footer class="ejh-savebar"><span>冻结、解冻及主动退款等未开放接口，不作模拟支持。</span><button class="btn primary" :disabled="busy||!ready">保存配置与模板</button></footer>
  </form>
<form v-else-if="tab==='open'" class="panel ejh-open-panel" @submit.prevent="openCards"><div class="ejh-section-heading"><div><span class="overline">ISSUE CARDS</span><h2>开卡</h2><p>选择已保存的模板，确认后顺序开卡并加入 Pro 银行卡信息。</p></div><CreditCard :size="28"/></div><div class="ejh-grid"><label class="field"><span>已保存模板</span><select v-model="openForm.template" @change="chooseTemplate"><option value="">请选择</option><option v-for="t in settings.templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label class="field"><span>数量</span><input v-model.number="openForm.count" type="number" min="1" max="50" required/></label><template v-if="openForm.input"><label class="field"><span>每张刷卡额度</span><input v-model="openForm.input.cardAmount" required/></label><label class="field"><span>到期日期</span><input v-model="openForm.input.activeDate" type="date" required/></label></template></div><p class="ejh-callout">顺序提交；网络错误或结果未知时停止。不要换请求编号重试，先在操作记录核实。</p><button class="btn primary" :disabled="busy||!ready||!openForm.input">{{busy?'处理中…':'确认开卡并加入 Pro'}}</button></form>
  <section v-else class="panel ejh-records"><div class="ejh-section-heading"><div><h2>{{tabs.find(t=>t[0]===tab)?.[1]}}</h2><p>{{sectionDescriptions[tab]}}</p></div><span class="ejh-record-count">{{filtered.length}} 条记录</span></div><div class="ejh-filterbar"><label class="ejh-search"><Search :size="16"/><input v-model="query" aria-label="搜索账号、尾号、流水号" placeholder="搜索账号、尾号、流水号" @input="page=1;targetCardID=''"/></label><select v-if="tab==='cases'" v-model="status" aria-label="回款状态筛选" @change="page=1"><option value="">全部状态</option><option v-for="(label,k) in returnStates" :key="k" :value="k">{{label}}</option></select><select v-if="tab==='trades'" v-model="status" aria-label="流水状态筛选" @change="page=1"><option value="">全部流水</option><option value="unmatched">回款待关联</option><option value="pending">回款待核实</option><option value="returned">已核实回款</option><option value="other">其他资金事件</option></select><button v-if="query||status" type="button" class="ejh-text-button" @click="clearFilters">清除筛选</button><div v-if="tab==='cards'" class="ejh-view-toggle" role="group" aria-label="卡片显示方式"><button type="button" :class="{active:cardView==='cards'}" :aria-pressed="cardView==='cards'" @click="setCardView('cards')"><LayoutGrid :size="15"/>卡片视图</button><button type="button" :class="{active:cardView==='list'}" :aria-pressed="cardView==='list'" @click="setCardView('list')"><List :size="15"/>列表视图</button></div></div><p v-if="tab==='cards' && targetCardID" class="ejh-search-hint">已定位 {{query}} 的开通卡。修改搜索或清除筛选可查看其他卡片。</p>
   <div v-if="tab==='cards' && cardView==='cards'" class="ejh-card-grid"><article v-for="c in visible" :key="c.id" class="ejh-card"><div class="ejh-card-top"><span class="ejh-card-symbol"><CreditCard :size="21"/></span><span class="ejh-state" :class="c.local?.available?'returned':c.error?'waiting':'unopened'">{{cardStatus(c)}}</span></div><h3>{{c.local?.name||'EJH 卡片'}}</h3><div class="ejh-card-number">{{c.remote.cardNo}}</div><div class="ejh-card-meta"><span>{{c.remote.cardCurrency}}</span><span>有效期 {{expiryLabel(c.remote.validityDate)}}</span></div><div class="ejh-card-balance"><div><small>卡余额</small><strong>{{c.balance_at ? c.balance : '尚未查询'}} <em v-if="c.balance_at">{{c.remote.cardCurrency}}</em></strong><small>查询于 {{formatTime(c.balance_at)}}</small></div><button class="ejh-text-button" type="button" :disabled="busy||!ready" @click="cardAction(c,'balance')">查询余额</button></div><p v-if="c.balance_error" class="danger-text">最近查询失败，保留旧值：{{c.balance_error}}</p><div class="ejh-card-capacity"><div><span>已开通账号</span><CardAccountPreview :rows="cardCases(c)"><button type="button" @click="showAccounts(c)"><strong>{{c.local?.opened_accounts||0}}</strong> / {{c.local?.account_limit||settings.default_max_accounts}}<ChevronDown :size="12"/></button></CardAccountPreview></div><div class="ejh-capacity-track"><span :style="{width:capacityPercent(c)+'%'}"></span></div><div class="ejh-capacity-hint"><span>在途 {{c.local?.pending_accounts||0}} · 剩余 {{c.local?.remaining_accounts||0}}</span><span>{{c.local?.max_accounts?'单卡上限':'EJH 默认'}}</span></div></div><div class="ejh-return-counts"><ReturnStatusBadge v-for="(label,k) in returnStates" :key="k" :state="k">{{label}} {{cardCases(c).filter(row=>row.state===k).length}}</ReturnStatusBadge></div><p v-if="c.error" class="danger-text">{{c.error}}</p><footer><span>{{c.local?.enabled?'已启用':'未启用'}} · {{c.local?.available?'可用于开通':'暂不可用'}}</span><button type="button" class="btn ghost compact" @click="managedID=c.id"><SlidersHorizontal :size="14"/>管理卡片</button></footer></article></div>
   <div v-else class="table-shell"><table v-if="tab==='cards'" class="ejh-card-table"><thead><tr><th>卡片 / 尾号</th><th>状态 / 有效期</th><th>卡余额</th><th>开通账号 / 名额</th><th>账号回款</th><th>操作</th></tr></thead><tbody><tr v-for="c in visible" :key="c.id"><td><strong>{{c.local?.name||'EJH 卡片'}}</strong><small>{{c.remote.cardNo}}</small><small>{{c.remote.orderNo}}</small></td><td><span class="ejh-state" :class="c.local?.available?'returned':c.error?'waiting':'unopened'">{{cardStatus(c)}}</span><small>{{c.local?.enabled?'已启用':'未启用'}} · {{c.local?.available?'可用于开通':'暂不可用'}}</small><small>有效期 {{expiryLabel(c.remote.validityDate)}} · {{c.remote.cardCurrency}}</small><small v-if="c.error" class="danger-text">{{c.error}}</small></td><td><strong>{{c.balance_at ? c.balance : '尚未查询'}} {{c.balance_at ? c.remote.cardCurrency : ''}}</strong><small>查询于 {{formatTime(c.balance_at)}}</small><small v-if="c.balance_error" class="danger-text">最近查询失败，保留旧值：{{c.balance_error}}</small></td><td><CardAccountPreview :rows="cardCases(c)"><button type="button" class="ejh-text-button" @click="showAccounts(c)">{{c.local?.opened_accounts||0}} / {{c.local?.account_limit||settings.default_max_accounts}} 个账号 <ChevronDown :size="12"/></button></CardAccountPreview><small>在途 {{c.local?.pending_accounts||0}} · 剩余 {{c.local?.remaining_accounts||0}}</small><small>{{c.local?.max_accounts?'单卡上限':'EJH 默认'}}</small></td><td><div class="ejh-return-counts"><ReturnStatusBadge v-for="(label,k) in returnStates" :key="k" :state="k">{{label}} {{cardCases(c).filter(row=>row.state===k).length}}</ReturnStatusBadge></div></td><td><div class="ejh-list-actions"><button type="button" class="btn ghost compact" :disabled="busy||!ready" @click="cardAction(c,'balance')">查询余额</button><button type="button" class="btn ghost compact" @click="managedID=c.id">管理卡片</button></div></td></tr></tbody></table><table v-else-if="tab==='cases'"><thead><tr><th>账号 / 开通订单</th><th>银行卡 / 套餐</th><th>状态</th><th>开通 / 申请时间</th><th>实际回款</th></tr></thead><tbody><tr v-for="c in visible" :key="c.id"><td>{{c.email}}<small>{{c.id}}{{c.deleted?' · 账号已删除':''}}</small></td><td>{{c.card_name}} · {{c.last4}}<small>{{c.provider}} / {{c.plan}}</small></td><td><ReturnStatusBadge :state="c.state"/><small v-if="overdue(c)" class="danger-text">超过提醒时长</small><small>{{c.request_source==='manual'?'人工标记合并成功':c.request_source==='remote'?'原合并流程成功标记':''}}</small></td><td>{{formatTime(c.opened_at)}}<small>{{formatTime(c.requested_at)}}</small></td><td><div v-for="t in c.returns" :key="t.id">{{tradeKinds[t.trade.tradeType]}} · <ReturnStatusBadge :state="t.confirmed ? 'returned' : 'unverified'"/><small>{{t.confirmed_amount}} {{t.confirmed_currency}} · {{t.source==='manual_verified'?'人工核实':'流水核实'}}</small><small>{{t.evidence}}</small></div><span v-if="!c.returns.length">尚无关联回款流水</span></td></tr></tbody></table>
 <table v-else-if="tab==='trades'"><thead><tr><th>流水 / 卡片</th><th>类型 / 入账状态</th><th>金额（原始字段）</th><th>商户 / 日期</th><th>归属 / 操作</th></tr></thead><tbody><tr v-for="t in visible" :key="t.id"><td>{{t.trade.tradeNo}}<small>{{t.trade.orderNo}} · {{t.trade.cardNo}}</small></td><td>{{tradeKinds[t.trade.tradeType]||t.trade.tradeType}}<small>{{t.trade.tradeStatus==='2'?'卡台已入账':'待入账 / 未知'}}</small></td><td>{{t.trade.tradeAmount}} {{t.trade.tradeCurrency}}<small>账单 {{t.trade.billAmount}} {{t.trade.billCurrency}}</small><small>refundBuyPrice：{{t.trade.refundBuyPrice||'未提供'}}</small></td><td>{{t.trade.collectionName}}<small>{{t.trade.tradeTime||t.trade.createdAt}}</small></td><td>{{data.cases.find(c=>c.id===t.payment_order_id)?.email||'未关联'}}<ReturnStatusBadge v-if="returnTypes.has(t.trade.tradeType)" :state="t.confirmed ? 'returned' : t.payment_order_id ? 'unverified' : 'unmatched'"/><small v-else>其他资金事件</small><template v-if="returnTypes.has(t.trade.tradeType)"><button v-if="!t.confirmed" class="btn ghost compact" :disabled="busy" @click="match(t)">关联 / 核实</button><button v-if="t.payment_order_id" class="btn ghost compact" :disabled="busy" @click="unmatch(t)">解除关联</button></template></td></tr></tbody></table>
 <table v-else-if="tab==='operations'"><thead><tr><th>请求编号</th><th>操作</th><th>状态</th><th>额度</th><th>时间 / 核实</th></tr></thead><tbody><tr v-for="o in visible" :key="o.id"><td>{{o.id}}<small>{{o.order_no}}</small></td><td>{{{open:'开卡',increase:'追加额度',cancel:'销卡'}[o.method]}} · {{o.automatic?'自动':'手动'}}</td><td>{{operationStates[o.status]||o.status}}<small class="danger-text">{{o.error}}</small><small>{{o.note}}</small></td><td>{{o.amount}} {{o.currency}}</td><td>{{formatTime(o.created_at)}}<button v-if="['unknown','submitting','import_pending'].includes(o.status)" class="btn ghost compact" :disabled="busy" @click="resolve(o)">核实结果</button></td></tr></tbody></table>
 <template v-else><details v-for="(a,i) in visible" :key="i"><summary>{{formatTime(a.at)}} · {{a.action||'关联核实'}}</summary><pre>{{JSON.stringify(a,null,2)}}</pre></details></template></div><div v-if="!visible.length" class="ejh-empty"><Search :size="26"/><strong>{{query || status ? '没有匹配的记录' : '暂无记录'}}</strong><p>{{query || status ? '试试其他关键词或清除筛选。' : '同步卡台记录后，数据会显示在这里。'}}</p></div><Pagination :page="page" :page-size="pageSize" :total="filtered.length" @update:page="page=$event" @update:page-size="pageSize=$event;page=1"/></section>
 <Teleport to="body"><div v-if="detail||matching||resolving||managedCard" class="modal-backdrop" @click.self="closeOverlay"><section class="modal ejh-modal" role="dialog" aria-modal="true" :aria-label="detail?.title || (managedCard ? '卡片管理' : matching ? '核实一次性回款' : '核实卡台操作')"><button type="button" class="icon-button ejh-modal-close" aria-label="关闭弹窗" :disabled="busy" @click="closeOverlay"><X :size="18"/></button><template v-if="detail"><h2>{{detail.title}}</h2><p v-if="detail.cases && !detail.cases.length" class="ejh-callout">暂无关联账号</p><ReturnCaseLine v-for="c in detail.cases||[]" :key="c.id" :row="c"/><pre v-if="detail.data">{{JSON.stringify(detail.data,null,2)}}</pre></template>
 <template v-else-if="managedCard">
 <div class="ejh-section-heading"><div><span class="overline">CARD DETAILS</span><h2>{{managedCard.local?.name || 'EJH 卡片'}}</h2><p>{{managedCard.remote.cardNo}} · {{cardStatus(managedCard)}}</p></div></div>
 <div class="ejh-detail-summary"><div><small>累计开通</small><strong>{{managedCard.local?.opened_accounts || 0}} 个账号</strong></div><div><small>单卡上限</small><strong>{{managedCard.local?.account_limit || settings.default_max_accounts}}</strong></div><div><small>卡片余额</small><strong>{{managedCard.balance || '未查询'}} {{managedCard.remote.cardCurrency}}</strong></div></div>
 <h3>查看与设置</h3><div class="ejh-management-actions"><button v-for="[a,label] in [['details','查看卡密'],['refresh','刷新卡片'],['balance','查询余额']]" :key="a" class="btn ghost" :disabled="busy" @click="cardAction(managedCard,a)">{{label}}</button><button class="btn ghost" @click="showAccounts(managedCard)">关联账号</button><template v-if="managedCard.local"><button class="btn ghost" :disabled="busy" @click="editLimit(managedCard)">设置上限</button><button class="btn ghost" :disabled="busy" @click="toggle(managedCard)">{{managedCard.local.enabled?'停用':'启用'}}</button></template></div>
 <div class="ejh-risk-zone"><h3>资金操作</h3><p>这些操作会提交至 EJH。请先核实卡片与金额，结果未知时不要重复提交。</p><div class="ejh-toolbar"><button class="btn ghost" :disabled="busy" @click="cardAction(managedCard,'increase')">追加额度</button><button class="btn danger" :disabled="busy" @click="cardAction(managedCard,'cancel')">销卡</button></div></div><p class="muted">冻结 / 解冻：供应商暂未开放。</p>
 </template>
 <form v-else-if="matching" @submit.prevent="saveMatch"><h2>核实一次性回款</h2><p>回款可与付款金额不同。请选择确切归属，不按金额或时间认定。撤销需核实授权已释放；普通入账状态不能单独证明释放完成。</p><label class="field"><span>同卡成功开通订单</span><select v-model="matchForm.payment_order_id" required><option value="">请选择</option><option v-for="c in matchingOrders" :key="c.id" :value="c.id">{{c.email}} · {{c.plan}} · {{c.id}}</option></select></label><label class="field"><span>原授权 / 清算流水</span><select v-model="matchForm.original_trade_id" required><option value="">请选择</option><option v-for="t in originals" :key="t.id" :value="t.id">{{t.trade.tradeNo}} · {{tradeKinds[t.trade.tradeType]}} · {{t.trade.tradeAmount}} {{t.trade.tradeCurrency}}</option></select></label><label class="field"><span>实际回款金额</span><input v-model="matchForm.amount" :required="matchForm.confirmed"/></label><label class="field"><span>实际回款币种（核实后填写）</span><input v-model="matchForm.currency" maxlength="3" :required="matchForm.confirmed"/></label><label class="field"><span>核实依据 / 业务对应关系</span><textarea v-model="matchForm.evidence" minlength="3" required/></label><label><input v-model="matchForm.confirmed" type="checkbox"/> 已核实该笔退款到账或授权撤销释放完成（人工核实，留审计）</label><button class="btn primary" :disabled="busy">保存</button></form>
 <form v-else-if="resolving" @submit.prevent="saveResolve"><h2>核实卡台操作</h2><p>未知结果不能直接重复提交，先核对卡台记录。</p><label class="field"><span>实际结果</span><select v-model="resolveForm.outcome"><option value="completed">已完成</option><option value="not_executed">确认未执行</option></select></label><label class="field"><span>EJH 开卡订单号</span><input v-model="resolveForm.order_no" :required="resolving.method==='open'&&resolveForm.outcome==='completed'"/></label><label class="field"><span>核实依据</span><textarea v-model="resolveForm.evidence" minlength="3" required/></label><button class="btn primary" :disabled="busy">提交核实</button></form><p v-if="message.type==='error'" class="danger-text">{{message.text}}</p><button class="btn" :disabled="busy" @click="closeOverlay">关闭</button></section></div></Teleport>
  <p class="ejh-footnote"><ShieldCheck :size="14"/>合并成功仅标记待回款；实际到账或授权释放需核对流水，不调用退款 / 撤销接口。</p>
 </div>
</template>
<style scoped>
